#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_TEXT_LEN 1024

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    char *endptr;
    long raw_shift = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0') {
        puts("USAGE");
        return 0;
    }

    int shift = (int)raw_shift;
    shift %= 26;
    if (shift < 0)
        shift += 26;

    const char *text = argv[2];
    size_t len = strlen(text);
    if (len > MAX_TEXT_LEN) {
        puts("USAGE");
        return 0;
    }

    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)text[i];
        if ('A' <= c && c <= 'Z') {
            c = (unsigned char)('A' + (c - 'A' + shift) % 26);
        } else if ('a' <= c && c <= 'z') {
            c = (unsigned char)('a' + (c - 'a' + shift) % 26);
        }
        putc(c, stdout);
    }
    putc('\n', stdout);
    return 0;
}
